options=read('/input/options')
from itertools import combinations
result=None
for combo in combinations(options,3):
 if all(combo[i]['owner']!=combo[j]['owner'] for i in range(3) for j in range(i+1,3)):
  ids=[c['id'] for c in combo]
  total_quality=sum(c['quality'] for c in combo)
  total_cost=sum(c['cost'] for c in combo)
  if total_quality>=15 and total_cost<=18:
   # Check requires closure
   requires_ok=True
   for c in combo:
    for r in c['requires']:
     if r not in ids:
      requires_ok=False
      break
    if not requires_ok:
     break
   if requires_ok:
    result=ids
    break
if result is None:
 result=[]

